// Inside an I/O callback:
const fs = require('fs');
fs.readFile(__filename, () => {
  setTimeout(() => console.log('timeout'), 0);
  setImmediate(() => console.log('immediate'));
});
// Logs: immediate → timeout (deterministic inside I/O phase)

// ❌ blocks the entire server while reading:
app.get('/sync', (_req, res) => {
  const data = fs.readFileSync('/tmp/huge.log', 'utf8');
  res.send(data.length);
});

// ✅ yields to other requests:
app.get('/async', async (_req, res) => {
  const data = await fs.promises.readFile('/tmp/huge.log', 'utf8');
  res.send(data.length);
});

