// package.json
{ "type": "module" } // .js files are now ESM

import { createReadStream, createWriteStream } from 'node:fs';
import { createGzip } from 'node:zlib';
import { pipeline } from 'node:stream/promises';

// Compress a huge file with ~constant memory:
await pipeline(
  createReadStream('access.log'),   // readable
  createGzip(),                     // transform
  createWriteStream('access.log.gz'), // writable
); // errors propagate & cleanup handled automatically

// config.ts — validated once at startup
import { z } from 'zod';

const Env = z.object({
  PORT: z.coerce.number().default(3000),
  DATABASE_URL: z.string().url(),
  NODE_ENV: z.enum(['development', 'test', 'production']),
});

export const config = Env.parse(process.env); // throws early w/ clear errors

// Run locally: node --env-file=.env index.js

// cluster.js — use all cores
import cluster from 'node:cluster';
import os from 'node:os';

if (cluster.isPrimary) {
  for (let i = 0; i < os.availableParallelism(); i++) cluster.fork();
  cluster.on('exit', (worker) => {
    console.log(`worker ${worker.process.pid} died — restarting`);
    cluster.fork();
  });
} else {
  await import('./server.js'); // each worker listens on same port
}

